function OverseaManageCafeCattyLetterDialog:RefreshShow()
    self.AniRoot:Play("OverseaManageCafeCattyLetterDialog_Go")
    self:RefreshStarShow()
    ---设置功能解锁
    self:SetFuncUnLock()
end

function OverseaManageCafeCattyLetterDialog:RefreshStarShow()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isToMax = component:GetIsToMaxStar()
    self.starGroupEnv:RefreshShow(isToMax)
end

function OverseaManageCafeCattyLetterDialog:PopUpStarUpSuccess()
    self.isStarUpEnd = false
    KTool.SetActive(self.ImgSignPlace,false)
    GameUtils.Request(Interfaces.MaidCoffeeStarUp,{},
            function(request,response)
                if checkInt(response.errCode) == 0 then
                    cs_coroutine.start(function()
                        local jsonData = response.data
                        self.AniRoot:Play("OverseaManageCafeCattyLetterDialog_UpStar")
                        self.starGroupEnv:PlayCurStarAni()
                        self.Spine.AnimationState:SetAnimation(0, "Play", false)
                        coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(2.25))
                        self.rewards = jsonData.rewards
                        ---更新一下星级
                        ---@type MaidCoffeePlayerComponent
                        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                        local curLevel = maidCoffeePlayerComponent:GetCafeStarLevel()
                        local starVo = MaidCoffeeUtils.GetMaidCoffeeStarUpVo(curLevel + 1)
                        if starVo then
                            GoodsUtils.ConsumeGoods(starVo.costs)
                        end
                        maidCoffeePlayerComponent:UpdateCafeStarLevel(curLevel + 1)
                        --local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
                        --local isCanLevelUpOrStarUp = maidCoffeeComponent:IsCanLevelUpOrStarUp()
                        --GameUtils.UpdateServerRedPointData({cafeLevelUp = isCanLevelUpOrStarUp and 0 or -1})
                        self.isStarUpEnd = true
                    end)
                end
            end)
end

function OverseaManageCafeCattyLetterDialog:PanelClose()
    if self.isStarUpEnd then
        local pRewards = checkTable(self.rewards)
        cs_coroutine.start(function()
            cs_coroutine.yield_return(UIModule.CloseDialog(self.controller))
            if not isNull(pRewards) and #pRewards > 0 then
                GoodsUtils.DrawRewards(pRewards, true)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = pRewards ,cb = self.callBack } })
            else
                if self.callBack then
                    self.callBack()
                end
            end
        end)
    end
end

function OverseaManageCafeCattyLetterDialog:SetFuncUnLock()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local curStar = component:GetMaidCoffeeCattyStarLevel()  --初始为0级  要取下一等级的对应等级
    local starVo = MaidCoffeeUtils.GetMaidCoffeeStarUpVo(curStar + 1)
    KTool.SetActive(self.UnlockCondition,starVo.ifFunction)
    if starVo and starVo.ifFunction then
        CfUtils.FillText(self.TxtState,starVo.desc)
    end
end

function OverseaManageCafeCattyLetterDialog:OnDrawTextureMouseUp()
    MaidCoffeeUtils.PlayMusicById(MaidCoffeeConstants.MaidCoffeeMusicName.CattySign)
    self:PopUpStarUpSuccess()
end

function OverseaManageCafeCattyLetterDialog:OnBtnCloseClick()
    self:PanelClose()
end

function OverseaManageCafeCattyLetterDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function OverseaManageCafeCattyLetterDialog:__delete()
    self.controller = nil
    CS.Engine.Modules.EventsModule.RemoveListener("DRAW_TEXTURE_MOUSE_UP", self.drawEventListener)
    self.drawEventListener = nil
    self.rewards = nil
end
return OverseaManageCafeCattyLetterDialog